private void closeAll(List<? extends Closeable> list) {
	try {
		for (Closeable closeable : list) {
			try {
				closeable.close();
			} catch (Exception e) {
				LOG.warn("Fail to close '{}'", closeable, e);
			}
		}
	} finally {
		list.clear();
	}
}

